template <typename T>
T max_val(T a, T b) {
    return (a > b) ? a : b;
}

// Usage (Type deduction)
int i = max_val(10, 20);
double d = max_val(3.5, 1.2);

template <typename T, int Size>
class StaticArray {
    T data[Size];
public:
    T& operator[](int index) {
        return data[index];
    }
};

// Usage
StaticArray<float, 5> arr;
arr[0] = 3.14f;

// Class Template Specialization (General)
template <typename T>
class Processor {
    /* Generic implementation */
    T process(T v) { return v + v; }
};

// Explicit Full Specialization for const char*
template <>
class Processor<const char*> {
public:
    const char* process(const char* s) {
        return "Specialized";
    }
};

// Usage
Processor<int> pi;
Processor<const char*> ps;

// Function Template Specialization
template <typename T>
void print_type(T v) { /* Generic print */ }

// Explicit Specialization for long
template <>
void print_type<long>(long v) {
    // Unique implementation for long type
}
